code_sketch:
Buffer& operator=(Buffer other) noexcept {      // copy (or move) made at the call site
    using std::swap;                             // ADL: member-wise, must not throw
    swap(data_, other.data_); swap(size_, other.size_);
    return *this;                                // other's dtor releases the old state
}
void swap(Buffer& o) noexcept { std::swap(data_, o.data_); std::swap(size_, o.size_); }
friend void swap(Buffer& a, Buffer& b) noexcept { a.swap(b); }

